// Graham-Andrew algorithm for convex hull
if (points.empty()) {
    return std::vector<Point2d>();
}

// Sort points
std::vector<Point2d> sortedPoints = points;
std::sort(sortedPoints.begin(), sortedPoints.end());

// Handle edge case: all points are the same
if (sortedPoints.size() == 1) {
    return sortedPoints;
}

// Remove duplicates
sortedPoints.erase(std::unique(sortedPoints.begin(), sortedPoints.end()), sortedPoints.end());

if (sortedPoints.size() == 1) {
    return sortedPoints;
}

// Build lower hull
std::vector<Point2d> lower;
for (const auto& p : sortedPoints) {
    while (lower.size() >= 2) {
        auto& p1 = lower[lower.size() - 2];
        auto& p2 = lower[lower.size() - 1];
        // Cross product to check orientation
        double cross = (p2.x() - p1.x()) * (p.y() - p1.y()) - (p2.y() - p1.y()) * (p.x() - p1.x());
        if (cross <= 0) {
            lower.pop_back();
        } else {
            break;
        }
    }
    lower.push_back(p);
}

// Build upper hull
std::vector<Point2d> upper;
for (auto it = sortedPoints.rbegin(); it != sortedPoints.rend(); ++it) {
    const auto& p = *it;
    while (upper.size() >= 2) {
        auto& p1 = upper[upper.size() - 2];
        auto& p2 = upper[upper.size() - 1];
        double cross = (p2.x() - p1.x()) * (p.y() - p1.y()) - (p2.y() - p1.y()) * (p.x() - p1.x());
        if (cross <= 0) {
            upper.pop_back();
        } else {
            break;
        }
    }
    upper.push_back(p);
}

// Remove last element of each hull to avoid duplicate points
lower.pop_back();
upper.pop_back();

// Combine hulls
std::vector<Point2d> hull = lower;
hull.insert(hull.end(), upper.begin(), upper.end());

return hull;

